      // au lieu d'abandonner.
      if (res.stormPath && res.stormPath.length && res.stormPathTx !== undefined && Math.hypot(res.stormPathTx - mate.x, res.stormPathTy - mate.y) > 0.75) res.stormPath = null;
      let etx = mate.x, ety = mate.y;
