          const sc = (C.ARTISAN_DRAW_SCALE_OVERRIDE && typeof C.ARTISAN_DRAW_SCALE_OVERRIDE[bid] === "number") ? C.ARTISAN_DRAW_SCALE_OVERRIDE[bid] : C.ARTISAN_DRAW_SCALE;
          const dw = bimg.width * sc, dh = bimg.height * sc;
